package redis

import (
	"context"
	"errors"

	redis "github.com/go-redis/cache/v9"
	"go.flipt.io/flipt/internal/cache"
	"go.flipt.io/flipt/internal/config"
)

const cacheType = "redis"

type Cache struct {
	c   *redis.Cache
	cfg config.CacheConfig
}

// NewCache creates a new redis cache with the provided cache config
func NewCache(cfg config.CacheConfig, r *redis.Cache) *Cache {
	return &Cache{cfg: cfg, c: r}
}

func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
	var value []byte
	key = cache.Key(key)
	if err := c.c.Get(ctx, key, &value); err != nil {
		if errors.Is(err, redis.ErrCacheMiss) {
			cache.Observe(ctx, cacheType, cache.Miss)
			return nil, false, nil
		}

		cache.Observe(ctx, cacheType, cache.Error)
		return nil, false, err
	}

	cache.Observe(ctx, cacheType, cache.Hit)
	return value, true, nil
}

func (c *Cache) Set(ctx context.Context, key string, value []byte) error {
	key = cache.Key(key)
	if err := c.c.Set(&redis.Item{
		Ctx:   ctx,
		Key:   key,
		Value: value,
		TTL:   c.cfg.TTL,
	}); err != nil {
		cache.Observe(ctx, cacheType, cache.Error)
		return err
	}

	return nil
}

func (c *Cache) Delete(ctx context.Context, key string) error {
	key = cache.Key(key)
	if err := c.c.Delete(ctx, key); err != nil {
		cache.Observe(ctx, cacheType, cache.Error)
		return err
	}

	return nil
}

func (c *Cache) String() string {
	return cacheType
}
package redis

import (
	"context"
	"fmt"
	"os"
	"testing"
	"time"

	goredis_cache "github.com/go-redis/cache/v9"
	goredis "github.com/redis/go-redis/v9"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/wait"
	"go.flipt.io/flipt/internal/config"
)

func TestSet(t *testing.T) {
	var (
		ctx         = context.Background()
		c, teardown = newCache(t, ctx)
	)

	defer teardown()

	err := c.Set(ctx, "key", []byte("value"))
	assert.NoError(t, err)
}

func TestGet(t *testing.T) {
	var (
		ctx         = context.Background()
		c, teardown = newCache(t, ctx)
	)

	defer teardown()

	err := c.Set(ctx, "key", []byte("value"))
	assert.NoError(t, err)

	v, ok, err := c.Get(ctx, "key")
	assert.NoError(t, err)
	assert.True(t, ok)
	assert.Equal(t, []byte("value"), v)

	v, ok, err = c.Get(ctx, "foo")
	assert.NoError(t, err)
	assert.False(t, ok)
	assert.Nil(t, v)

	v, ok, err = c.Get(ctx, "key")
	assert.NoError(t, err)
	assert.True(t, ok)
	assert.Equal(t, []byte("value"), v)
}

func TestDelete(t *testing.T) {
	var (
		ctx         = context.Background()
		c, teardown = newCache(t, ctx)
	)

	defer teardown()

	err := c.Set(ctx, "key", []byte("value"))
	assert.NoError(t, err)

	v, ok, err := c.Get(ctx, "key")
	assert.NoError(t, err)
	assert.True(t, ok)
	assert.Equal(t, []byte("value"), v)

	err = c.Delete(ctx, "key")
	assert.NoError(t, err)

	v, ok, err = c.Get(ctx, "key")
	assert.NoError(t, err)
	assert.False(t, ok)
	assert.Nil(t, v)
}

type redisContainer struct {
	testcontainers.Container
	host string
	port string
}

func setupRedis(ctx context.Context) (*redisContainer, error) {
	req := testcontainers.ContainerRequest{
		Image:        "redis:alpine",
		ExposedPorts: []string{"6379/tcp"},
		WaitingFor:   wait.ForLog("* Ready to accept connections"),
	}
	container, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	if err != nil {
		return nil, err
	}

	mappedPort, err := container.MappedPort(ctx, "6379")
	if err != nil {
		return nil, err
	}

	hostIP, err := container.Host(ctx)
	if err != nil {
		return nil, err
	}

	return &redisContainer{Container: container, host: hostIP, port: mappedPort.Port()}, nil
}

func newCache(t *testing.T, ctx context.Context) (*Cache, func()) {
	t.Helper()

	if testing.Short() {
		t.Skip("skipping test in short mode")
	}

	var (
		redisAddr   = os.Getenv("REDIS_HOST")
		redisCancel = func(context.Context) error { return nil }
	)

	if redisAddr == "" {
		t.Log("Starting redis container.")

		redisContainer, err := setupRedis(ctx)
		require.NoError(t, err, "Failed to start redis container.")

		redisCancel = redisContainer.Terminate
		redisAddr = fmt.Sprintf("%s:%s", redisContainer.host, redisContainer.port)
	}

	rdb := goredis.NewClient(&goredis.Options{
		Addr: redisAddr,
	})

	cache := NewCache(config.CacheConfig{
		TTL: 30 * time.Second,
	}, goredis_cache.New(&goredis_cache.Options{
		Redis: rdb,
	}))

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	teardown := func() {
		_ = redisCancel(shutdownCtx)
		cancel()
	}

	return cache, teardown
}

package config

import (
	"encoding/json"
	"time"

	"github.com/spf13/viper"
)

// cheers up the unparam linter
var _ defaulter = (*CacheConfig)(nil)

// CacheConfig contains fields, which enable and configure
// Flipt's various caching mechanisms.
//
// Currently, flipt support in-memory and redis backed caching.
type CacheConfig struct {
	Enabled bool              `json:"enabled" mapstructure:"enabled" yaml:"enabled"`
	TTL     time.Duration     `json:"ttl,omitempty" mapstructure:"ttl" yaml:"ttl,omitempty"`
	Backend CacheBackend      `json:"backend,omitempty" mapstructure:"backend" yaml:"backend,omitempty"`
	Memory  MemoryCacheConfig `json:"memory,omitempty" mapstructure:"memory" yaml:"memory,omitempty"`
	Redis   RedisCacheConfig  `json:"redis,omitempty" mapstructure:"redis" yaml:"redis,omitempty"`
}

func (c *CacheConfig) setDefaults(v *viper.Viper) error {
	v.SetDefault("cache", map[string]any{
		"enabled": false,
		"backend": CacheMemory,
		"ttl":     1 * time.Minute,
		"redis": map[string]any{
			"host":     "localhost",
			"port":     6379,
			"password": "",
			"db":       0,
		},
		"memory": map[string]any{
			"enabled":           false, // deprecated (see below)
			"eviction_interval": 5 * time.Minute,
		},
	})

	return nil
}

// IsZero returns true if the cache config is not enabled.
// This is used for marshalling to YAML for `config init`.
func (c CacheConfig) IsZero() bool {
	return !c.Enabled
}

// CacheBackend is either memory or redis
// TODO: can we use a string here instead?
type CacheBackend uint8

func (c CacheBackend) String() string {
	return cacheBackendToString[c]
}

func (c CacheBackend) MarshalJSON() ([]byte, error) {
	return json.Marshal(c.String())
}

func (c CacheBackend) MarshalYAML() (interface{}, error) {
	return c.String(), nil
}

const (
	_ CacheBackend = iota
	// CacheMemory ...
	CacheMemory
	// CacheRedis ...
	CacheRedis
)

var (
	cacheBackendToString = map[CacheBackend]string{
		CacheMemory: "memory",
		CacheRedis:  "redis",
	}

	stringToCacheBackend = map[string]CacheBackend{
		"memory": CacheMemory,
		"redis":  CacheRedis,
	}
)

// MemoryCacheConfig contains fields, which configure in-memory caching.
type MemoryCacheConfig struct {
	EvictionInterval time.Duration `json:"evictionInterval,omitempty" mapstructure:"eviction_interval" yaml:"eviction_interval,omitempty"`
}

// RedisCacheConfig contains fields, which configure the connection
// credentials for redis backed caching.
type RedisCacheConfig struct {
	Host            string        `json:"host,omitempty" mapstructure:"host" yaml:"host,omitempty"`
