		if conf.auth.enabled() {
			flags = append(flags, "--token", bootstrapToken)
		}

		ns := "default"
		if conf.namespace != "" {
			ns = conf.namespace
		}

		seed := base.File(path.Join(singleRevisionTestdataDir, ns+".yaml"))

		var (
			// create unique instance for test case
