func cacheTLS(ctx context.Context, client *dagger.Client, base, flipt *dagger.Container, conf testConfig) func() error {
	caPEM, certPEM, keyPEM, err := redisTLSCertificates()
	if err != nil {
		return func() error { return err }
	}

	redis := client.Container().
		From("redis:alpine").
		WithNewFile("/tls/ca.pem", dagger.ContainerWithNewFileOpts{Contents: caPEM}).
		WithNewFile("/tls/server.pem", dagger.ContainerWithNewFileOpts{Contents: certPEM}).
		WithNewFile("/tls/server.key", dagger.ContainerWithNewFileOpts{Contents: keyPEM}).
		WithExposedPort(6379).
		WithExec([]string{"redis-server", "--port", "0", "--tls-port", "6379", "--tls-cert-file", "/tls/server.pem", "--tls-key-file", "/tls/server.key", "--tls-ca-cert-file", "/tls/ca.pem", "--tls-auth-clients", "no", "--protected-mode", "no"}).
		AsService()

	flipt = flipt.
		WithServiceBinding("redis", redis).
		WithNewFile("/etc/flipt/redis-ca.pem", dagger.ContainerWithNewFileOpts{Contents: caPEM}).
		WithEnvVariable("FLIPT_CACHE_ENABLED", "true").
		WithEnvVariable("FLIPT_CACHE_BACKEND", "redis").
		WithEnvVariable("FLIPT_CACHE_REDIS_HOST", "redis").
		WithEnvVariable("FLIPT_CACHE_REDIS_REQUIRE_TLS", "true").
		WithEnvVariable("FLIPT_CACHE_REDIS_CA_CERT_PATH", "/etc/flipt/redis-ca.pem")

	return suite(ctx, "api", base, flipt.WithExec(nil), conf)
}

func redisTLSCertificates() (caPEM, certPEM, keyPEM string, err error) {
	caKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", "", "", err
